document.addEventListener('DOMContentLoaded',function(){'use strict';const navLinks=document.querySelectorAll('.nav-scroll a');navLinks.forEach(function(link){link.addEventListener('click',function(event){event.preventDefault();const hash=this.getAttribute('href');const target=document.querySelector(hash);if(target){this.classList.remove('text-decoration-none');const siblings=[...this.parentElement.children].filter(el=>el!==this);siblings.forEach(sib=>sib.classList.add('text-decoration-none'));const offset=target.offsetTop-70;window.scrollTo({top:offset,behavior:'smooth'})}})});Fancybox.bind("[data-fancybox]",{Thumbs:!1,})})